INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (68, 180, 'BOPP BOPET cigarette tear tape envelop tear strip', '../upload/image/20180929/20180929103823_98225.jpg', '<p></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>BOPP BOPET cigarette tear tape envelop tear strip</strong></span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">BOPP/BOPET self adhesive tear tape lines were for packing/opening of cigarette packs and other packs. it was self adhesive tear tape.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> tear tape have BOPP tear tape, BOPET tear tape,cigarette tear tape,self adhesive tear tape,and other non cigarette usage tear tapes Various sizes for adhesive tear tape:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> a) Thickness of tear tape: 25-40UM b) Width of tear tape rolls: 1.6mm-6.0mm</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> c) Length of tear tape rolls: 5,000m-70,000m</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 2) Printing design: a) Color printing of tear tape rolls: gold, single gold, single silver, full solid red, yellow,white,black, etc. b) Logo printing of tear tape rolls: ink printing logo, laser, holographic effect</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 3.) Packing for of tear tape rolls: Cartons (16rolls/carton)</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Certification: ISO9001, ISO14001, OHSMS18000 </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> 4.) others: anti-counterfeiting tear tape,lightness beam laser labels,water-transfer boardpaper,super crystal brightness cigarette tipping paper,envelop tear strip</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Specitications for Self Adhesive Tear Strio Size 1.6 mm. X 16.000 m. </span></p> <p></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1. Description</span></p> <p><br/></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">: Transparent Tear Strip in reel </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">: Inside diameter of core 29-30 mm. : Outside diameter of core 34-35 </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">: Length of core 100士2mm.</span><br/></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">2. Size</span></p> <p><br/></p> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">: Shape of core similar to the sample</span> <p><br/></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">: </span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1.5-1.7 mm. X 16,000 m. per reel</span></p> <p></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Tensile Strength</span></p> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">: Not less than19 N/1.6 mm. </span> <p><br/></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (68, 110, 'BOPP BOPET cigarette tear tape envelop tear strip', '../upload/image/20180929/20180929104114_15457.jpg', '<p></p><p>BOPP BOPET cigarette tear tape envelop tear strip</p> <p>BOPP/BOPET self adhesive tear tape lines were for packing/opening of cigarette packs and other packs. it was self adhesive tear tape.<br/> tear tape have BOPP tear tape, BOPET tear tape,cigarette tear tape,self adhesive tear tape,and other non cigarette usage tear tapes Various sizes for adhesive tear tape:<br/> a) Thickness of tear tape: 25-40UM b) Width of tear tape rolls: 1.6mm-6.0mm<br/> c) Length of tear tape rolls: 5,000m-70,000m<br/> 2) Printing design: a) Color printing of tear tape rolls: gold, single gold, single silver, full solid red, yellow,white,black, etc. b) Logo printing of tear tape rolls: ink printing logo, laser, holographic effect<br/> 3.) Packing for of tear tape rolls: Cartons (16rolls/carton)<br/> Certification: ISO9001, ISO14001, OHSMS18000 <br/> 4.) others: anti-counterfeiting tear tape,lightness beam laser labels,water-transfer boardpaper,super crystal brightness cigarette tipping paper,envelop tear strip</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (68, 111, 'tear hair tape self adhesive tear strip', '../upload/image/20180922/20180922163905_89447.jpg', '<p></p><p>tear hair tape self adhesive tear strip</p> <p>Self adhesive tear tape (tear strip) are used for opening of cigarette packs, biscuit bag/boxes, chewing gum bags, medicine pieces, garments, CD, and so forth.<br/> Tear tapes included BOPP tear tape,BOPET tear tape,adhesive tear tape ,cigarette tear tape,BOPET tear tape and other non cigarette usage tear tapes<br/> 1) Material of Self adhesive tear tape: BOPET, BOPP,VMOPP,VMOPP. <br/> 2) Width of tear tape rolls: 1.2 - 8.0mm ( such as:1.6mm,1.8mm,2.0mm,2.5mm,3.0mm,4.5mm,6.0mm,8.0mm..)<br/> 3) Run length of tear tape rolls: 5,000 - 50,000m/spool<br/> 4) Color of tear tape rolls: red, gold, silver, green, blue, yellow, transparent, and so forth.<br/> 5) Inner packing for of tear tape rolls: using cartons. Outer packing:using pallets.<br/> 4.) others: anti-counterfeiting tear tape,lightness beam laser labels,water-transfer boardpaper,super crystal brightness cigarette tipping paper</p>', '2026-09-06 20:58:45');